begin;
create function pg_temp.check(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'Assertion failed: %',label;end if;end$$;
create function pg_temp.denied(q text,state text,label text) returns void language plpgsql as $$begin begin execute q;exception when others then if sqlstate=state then return;end if;raise exception '% unexpected %: %',label,sqlstate,sqlerrm;end;raise exception 'Expected rejection: %',label;end$$;
grant execute on function pg_temp.check(boolean,text),pg_temp.denied(text,text,text) to authenticated,service_role;
create temp table fixture(key text primary key,id uuid);
grant select,insert on fixture to authenticated,service_role;
insert into auth.users values('40000000-0000-0000-0000-000000000001','{}'),('40000000-0000-0000-0000-000000000002','{}'),('40000000-0000-0000-0000-000000000003','{}');
insert into public.server_roles values('40000000-0000-0000-0000-000000000001','teacher'),('40000000-0000-0000-0000-000000000003','admin');
set local request.jwt.claim.sub='40000000-0000-0000-0000-000000000002';set local role authenticated;
select pg_temp.denied('select public.create_course(''Spoofed'')','42501','student cannot create course');
reset role;
set local request.jwt.claim.sub='40000000-0000-0000-0000-000000000001';set local role authenticated;
select public.save_profile('Teacher Name',true);
insert into fixture select 'course',(public.create_course('Original course')).id;
select pg_temp.check((select created_by=auth.uid() and status='draft' from public.courses),'course owner bound to teacher');
select pg_temp.denied('insert into public.courses(slug,title,source_policy) values(''forged'',''forged'',''fixture'')','42501','direct owner forgery blocked');
select pg_temp.denied('select public.publish_course((select id from fixture where key=''course''))','55000','empty course not published');
insert into fixture select 'level',(public.create_level((select id from fixture where key='course'),'Level',0)).id;
insert into fixture select 'book',(public.create_book((select id from fixture where key='level'),'Book',0,'fixture edition','fixture reference')).id;
select public.set_book_source((select id from fixture where key='book'),'{"edition":"fixture edition","page_start":1,"page_end":2}');
insert into fixture select 'unit',(public.create_unit((select id from fixture where key='book'),'Unit',0)).id;
insert into fixture select 'lesson',(public.create_lesson((select id from fixture where key='unit'),'Lesson',0)).id;
select pg_temp.denied('select public.save_lesson((select id from fixture where key=''lesson''),1,''{"source_locator":{"page":0}}'')','P0001','invalid source page rejected');
select public.save_lesson((select id from fixture where key='lesson'),1,'{"status":"published","source_locator":{"edition":"fixture","page":3,"unknown_manifest_field":"kept"}}','{"blocks":[{"step":"introduction","kind":"text","body":{"text":"Introduction"},"position":0}],"vocabulary":[{"text_ar":"كِتَابٌ","translation":"Book","position":0,"root":"كتب","part_of_speech":"noun","gender":"masculine","number":"singular","forms":{"plural":"كُتُبٌ"},"example_ar":"هَذَا كِتَابٌ","example_translation":"This is a book","level":"introductory"}],"grammar":[{"title":"Grammar","explanation":"Example","position":0,"part_of_speech":"noun","forms":[],"example_ar":"كِتَابٌ"}]}');
select pg_temp.check((select forms->>'plural'='كُتُبٌ' and root='كتب' from public.vocabulary),'linguistic metadata preserved');
select pg_temp.check((select source_locator->>'unknown_manifest_field'='kept' from public.lessons),'source unknown fields preserved');
select public.publish_course((select id from fixture where key='course'));
select public.save_exercise('40000000-0000-0000-0000-000000000700',(select id from fixture where key='lesson'),0,'{"kind":"text","title":"Exercise","grading_mode":"automatic","published":true}','[{"id":"40000000-0000-0000-0000-000000000800","prompt":{"text":"Say yes"},"position":0,"accepted_answers":["yes"]}]');
insert into fixture select 'group',(public.create_group((select id from fixture where key='course'),'Group')).id;
select pg_temp.denied('select public.set_group_member((select id from fixture where key=''group''),''40000000-0000-0000-0000-000000000002'',true)','42501','teacher cannot assign own students');
reset role;set local request.jwt.claim.sub='40000000-0000-0000-0000-000000000003';set local role authenticated;
select public.set_group_member((select id from fixture where key='group'),'40000000-0000-0000-0000-000000000002',true);
-- Admins can create a real catalog without a preexisting teachers row.
insert into fixture select 'admin_course',(public.create_course('Admin course')).id;
insert into fixture select 'admin_group',(public.create_group((select id from fixture where key='admin_course'),'Admin group')).id;
reset role;set local request.jwt.claim.sub='40000000-0000-0000-0000-000000000001';set local role authenticated;
insert into fixture select 'assignment',(public.create_assignment((select id from fixture where key='group'),'40000000-0000-0000-0000-000000000700','Homework')).id;
insert into fixture select 'notification',(public.create_notification('40000000-0000-0000-0000-000000000002',(select id from fixture where key='group'),'assignment','{"title":"Homework","text":"Please study"}','40000000-0000-0000-0000-000000000900')).id;
select pg_temp.check(public.notification_dispatch_status((select id from fixture where key='notification'))->>'state'='not_dispatched','notification not falsely delivered');
reset role;set local request.jwt.claim.sub='40000000-0000-0000-0000-000000000002';set local role authenticated;
select public.register_push_token('workflow-private-push-token');
insert into fixture select 'study',(public.start_study_session((select id from fixture where key='lesson'),'40000000-0000-0000-0000-000000000901')).id;
select public.end_study_session((select id from fixture where key='study'),2);
select pg_temp.check((select count(*)=0 from public.study_progress),'study time never grants progress');
insert into fixture select 'submission',(public.submit_assignment((select id from fixture where key='assignment'),0,'40000000-0000-0000-0000-000000000902','{"text":"first"}')).id;
select pg_temp.check((select status='submitted' from public.submissions),'initial submission status');
select pg_temp.denied('select public.notification_dispatch_status((select id from fixture where key=''notification''))','42501','recipient cannot send teacher notification');
select pg_temp.check(position('workflow-private-push-token' in public.account_export()::text)=0,'export excludes push secrets');
select pg_temp.check(position('accepted_answers' in public.account_export()::text)=0,'export excludes answer keys');
reset role;set local request.jwt.claim.sub='40000000-0000-0000-0000-000000000001';set local role authenticated;
select public.request_submission_revision((select id from fixture where key='submission'),1,'Please revise');
select public.request_submission_revision((select id from fixture where key='submission'),1,'Please revise');
select pg_temp.check((select count(*)=1 from public.revision_requests),'revision request replay idempotent');
select pg_temp.denied('select public.grade_submission((select id from fixture where key=''submission''),1,100,''early'')','55000','cannot grade awaiting revision');
select pg_temp.check(jsonb_array_length(public.account_export()->'data'->'submissions')=0,'teacher export excludes assigned student private work');
reset role;
update public.assignments set due_at=now()-interval '1 minute';
set local request.jwt.claim.sub='40000000-0000-0000-0000-000000000002';set local role authenticated;
select public.submit_assignment((select id from fixture where key='assignment'),1,'40000000-0000-0000-0000-000000000903','{"text":"revised"}');
select pg_temp.check((select status='submitted' and revision=2 from public.submissions),'requested revision allowed after deadline');
select pg_temp.check((select resolved_at is not null from public.revision_requests),'old request resolved');
reset role;set local request.jwt.claim.sub='40000000-0000-0000-0000-000000000001';set local role authenticated;
select public.grade_submission((select id from fixture where key='submission'),2,90,'Well done');
select pg_temp.check((select status='graded' from public.submissions),'graded status controlled by teacher');
select pg_temp.check((select count(*)=4 from public.submission_status_history),'all state transitions retained');
reset role;set local request.jwt.claim.sub='';set local role service_role;
select pg_temp.denied('select public.claim_notification_dispatch((select id from fixture where key=''notification''),''40000000-0000-0000-0000-000000000002'')','42501','dispatch actor claim cannot be student');
select pg_temp.check((public.claim_notification_dispatch((select id from fixture where key='notification'),'40000000-0000-0000-0000-000000000001')->>'duplicate')::boolean=false,'notification dispatch claimed once');
select public.finish_notification_dispatch((select id from fixture where key='notification'),1,0);
select pg_temp.check((public.claim_notification_dispatch((select id from fixture where key='notification'),'40000000-0000-0000-0000-000000000001')->>'duplicate')::boolean,'notification replay never sends again');
select pg_temp.denied('select public.purge_account_data(''40000000-0000-0000-0000-000000000001'')','42501','purge requires prior explicit confirmation');
reset role;set local request.jwt.claim.sub='40000000-0000-0000-0000-000000000001';set local role authenticated;
select public.prepare_media_upload(null,'audio/mp4',3,false);
select public.prepare_media_upload((select id from fixture where key='lesson'),'image/png',3,false);
select pg_temp.denied('select public.request_account_deletion(false)','42501','delete confirmation mandatory');
select pg_temp.check(jsonb_array_length(public.request_account_deletion(true)->'objects')=2,'plan removes every owned upload including shared-course assets');
select pg_temp.check(not public.has_server_role('teacher'),'pending deletion disables server role');
select pg_temp.denied('update public.user_settings set stt_consent=true where user_id=auth.uid()','42501','pending account direct writes blocked');
select pg_temp.denied('select public.record_event(gen_random_uuid(),''draft_saved'',''{}'')','42501','pending account RPC writes blocked');
reset role;set local request.jwt.claim.sub='';set local role service_role;
select public.purge_account_data('40000000-0000-0000-0000-000000000001');
select public.purge_account_data('40000000-0000-0000-0000-000000000001');
select pg_temp.check((select display_name='' from public.profiles where id='40000000-0000-0000-0000-000000000001'),'PII cleared before auth deletion');
select pg_temp.check((select count(*)=1 from public.submissions),'other student submissions preserved');
select pg_temp.check((select score=90 and teacher_id is null from public.grades),'other student grade retained without teacher identity');
select pg_temp.check((select teacher_id is null and archived_at is not null from public.groups where id=(select id from fixture where key='group')),'teacherless groups archived');
select pg_temp.check((select count(*)=1 from public.media),'shared course media preserved');
select pg_temp.check((select owner_id is null and upload_state='deleted' from public.media),'shared asset tombstoned without retaining upload/identity');
select pg_temp.check((select count(*)=0 from public.notifications),'departing teacher messages purged');
reset role;
-- Emulate successful Auth admin DELETE and confirm all remaining FKs permit it.
delete from auth.users where id='40000000-0000-0000-0000-000000000001';
select pg_temp.check(not exists(select 1 from public.profiles where id='40000000-0000-0000-0000-000000000001'),'profile cascades with hard auth deletion');
select pg_temp.check((select created_by is null from public.courses where id=(select id from fixture where key='course')),'published course attribution anonymized');
select pg_temp.check(exists(select 1 from auth.users where id='40000000-0000-0000-0000-000000000002'),'other account remains intact');
set local role service_role;
select pg_temp.check(jsonb_array_length(public.claim_account_media_cleanup())=0,'cleanup waits for token expiry');
update private.account_media_cleanup_jobs set not_before=now()-interval '1 minute';
select pg_temp.check(jsonb_array_length(public.claim_account_media_cleanup())=1,'late upload cleanup leased once');
select pg_temp.check(jsonb_array_length(public.claim_account_media_cleanup())=0,'concurrent cleanup cannot reclaim active lease');
select public.finish_account_media_cleanup((select id from private.account_media_cleanup_jobs),true);
select pg_temp.check((select user_id is null and objects='[]'::jsonb and completed_at is not null from private.account_media_cleanup_jobs),'cleanup removes last opaque identifiers and object paths');
reset role;
rollback;
